# Cerberus Agent __VERSION__ one-line installer, generated by the release build. Do not edit.
# Elevated PowerShell:      irm <url of this file> | iex
# Download and verify only: & ([scriptblock]::Create((irm <url of this file>))) -DownloadOnly
# The installer is fetched from the URL below and must match the length and SHA-256 published with this release.
# It is verified under a read lock and opened from that locked file with its own UI (EULA, server enrollment code).
param([switch]$DownloadOnly)

function Install-CerberusAgentRelease([switch]$DownloadOnly) {
  $ErrorActionPreference = 'Stop'
  $ProgressPreference = 'SilentlyContinue'
  $version = '__VERSION__'
  $url = '__ARTIFACT_URL__'
  $sha256 = '__SHA256__'
  $length = [long]'__LENGTH__'

  $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
  $admin = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
  if (-not $admin -and -not $DownloadOnly) { throw 'Run PowerShell as Administrator to install the Cerberus Agent.' }
  [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

  $root = if ($admin) { Join-Path $env:ProgramData 'Cerberus\Install' } else { Join-Path ([IO.Path]::GetTempPath()) 'Cerberus.Install' }
  $dir = Join-Path $root ([guid]::NewGuid().ToString('N'))
  $null = New-Item -ItemType Directory -Path $dir -Force
  if ($admin) {
    # Only Administrators and SYSTEM may write the download folder.
    $acl = New-Object Security.AccessControl.DirectorySecurity
    $acl.SetAccessRuleProtection($true, $false)
    foreach ($sid in 'S-1-5-32-544', 'S-1-5-18') {
      $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule(
        (New-Object Security.Principal.SecurityIdentifier($sid)), 'FullControl', 'ContainerInherit, ObjectInherit', 'None', 'Allow')))
    }
    Set-Acl -LiteralPath $dir -AclObject $acl
  }
  if (@(Get-ChildItem -LiteralPath $dir -Force).Count -ne 0) { throw "Download folder is not empty: $dir" }

  $msi = Join-Path $dir ([IO.Path]::GetFileName(([Uri]$url).AbsolutePath))
  Write-Host "Downloading Cerberus Agent $version ..."
  Invoke-WebRequest -Uri $url -OutFile $msi -UseBasicParsing

  # The read lock blocks writes, renames and deletes until msiexec has finished with the verified bytes.
  $stream = [IO.File]::Open($msi, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
  $verified = $false
  try {
    if ($stream.Length -ne $length) { throw "Downloaded installer has $($stream.Length) bytes, expected $length." }
    $hasher = [Security.Cryptography.SHA256]::Create()
    try { $actual = ([BitConverter]::ToString($hasher.ComputeHash($stream)) -replace '-', '').ToLowerInvariant() } finally { $hasher.Dispose() }
    if ($actual -cne $sha256) { throw 'Downloaded installer does not match the published SHA-256.' }
    $verified = $true
    if ($DownloadOnly) { Write-Host "Verified: $msi"; return }
    $log = Join-Path $dir 'install.log'
    Write-Host "Opening the Cerberus Agent $version installer ..."
    $process = Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\msiexec.exe') -Wait -PassThru `
      -ArgumentList @('/i', ('"{0}"' -f $msi), '/l*v', ('"{0}"' -f $log))
    $code = $process.ExitCode
  } finally {
    $stream.Dispose()
    if (-not $verified) { Remove-Item -LiteralPath $msi -Force -ErrorAction SilentlyContinue }
  }

  if ($code -eq 0 -or $code -eq 3010 -or $code -eq 1641) {
    Remove-Item -LiteralPath $msi -Force
    if ($code -eq 0) { Write-Host "Cerberus Agent $version installed." } else { Write-Host "Cerberus Agent $version installed. Restart Windows to finish." }
    return
  }
  if ($code -eq 1602) { Remove-Item -LiteralPath $msi -Force; Write-Host 'Installation cancelled.'; return }
  throw "Installer exited with code $code. Log: $log"
}

Install-CerberusAgentRelease -DownloadOnly:$DownloadOnly
